int main(int argc, char **argv)
{
  int checkpoint;
  mem_check_heap_init();
  if (argc > 1 && strcmp(argv[1], proview_text) == 0) {
    checkpoint = mem_init_checkpoint(false);
    nglSetProViewPS2(true);
    nslPreInitProviewModePS2(true);
  } else {
    checkpoint = mem_init_checkpoint(true);
    nslPreInitProviewModePS2(false);
  }
  pstring spideyname = game_name;
  application_name = argv[0];
  g_ksps_path = argv[0];
  sceSifInitRpc(0);
  nglPrintf(welcome_text, application_name, spideyname.c_str());
  UseStaticBallocMem();
  int DiskType;
  if (nglUsingProView == false) {
    sceCdInit(0);
    DiskType = 2;
    sceCdMmode(DiskType == 2 ? 2 : 1);
    while (!sceSifRebootIop(load_iop_from_host ? iop_host : iop_cd));
    while (!sceSifSyncIop());
    sceSifInitRpc(0);
  }
  sceCdInit(0);
  DiskType = 2;
  sceCdMmode(DiskType == 2 ? 2 : 1);
  sceFsReset();
  nslPreInitCdDvdModePS2(DiskType == 2 ? 1 : 0);
  if (nglUsingProView) g_debug_flags |= 0x80;
  int mainThreadId = GetThreadId();
  ChangeThreadPriority(mainThreadId, 1);
  acquire_stash_bufferspace(BIG_ASS_BUFFER_SIZE);
  os_alloc_init();
  os_developer_options::create_inst();
  debug_print(parsed_text);
  nglSetSystemCallbacks(nglhooks);
  nglSetBufferSize(0, os_developer_options::inst()->ints[0] * 1024);
  nglSetBufferSize(1, os_developer_options::inst()->ints[1] * 1024);
  nglSetBufferSize(2, os_developer_options::inst()->ints[2] * 1024);
  nglSetBufferSize(3, os_developer_options::inst()->ints[3] * 1024);
  nglSetTVMode(1);
  nglInit();
  nglSetIFLSpeed(60.0f);
  if (!os_developer_options::inst()->flags[0] || nglUsingProView) register_exception_handlers();
  low_level_console_init();
  low_level_console_print(console_text);
  llc_memory_log();
  init_fast_acos_table();
  init_fast_sin_table();
  application_startup();
  application_run();
  application_shutdown();
  release_stash_bufferspace();
  mem_check_leaks_since_checkpoint(checkpoint, 1);
  return 0;
}
